/*
 * A043757  Numbers n such that number of runs in the base 2 representation of
 *          n is congruent to 3 mod 9.
 * https://oeis.org/A043757
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   sequence of n whose binary run count ≡ 3 (mod 9) – generated by
 *            a simple search that records qualifying values
 * Range:     u8 n <= 53, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Cache of previously found terms.  cache[0] holds a(1).  */
static seq_t *cache  = NULL;
static idx_t  cache_len = 0;      /* number of cached terms   */
static idx_t  cache_cap = 0;      /* allocated capacity       */
static idx_t  next_candidate = 1; /* first integer to test    */

/* Count the number of binary runs in x.  Runs are groups of consecutive
   equal bits.  Only operations allowed on seq_t are used. */
static int binary_run_count(seq_t x)
{
    int runs = 0;
    int prev = -1;
    while (x) {
        int bit = (int)(x & (seq_t)1);
        if (bit != prev) {
            runs++;
            prev = bit;
        }
        x >>= 1;
    }
    return runs;
}

/* Append a value to the cache, growing the array if necessary. */
static void cache_push(seq_t val)
{
    if (cache_len + 1 > cache_cap) {
        idx_t new_cap = cache_cap ? cache_cap * 2 : (idx_t)64;
        seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
        if (tmp == NULL) abort(); /* allocation failure */
        cache = tmp;
        cache_cap = new_cap;
    }
    cache[cache_len++] = val;
}

/* OEIS sequence A043757.  a(1) = first qualifying number, etc. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* Undefined below the offset. */

    /* Ensure we have at least n terms stored. */
    while (cache_len < n) {
        if (binary_run_count((seq_t)next_candidate) % 9 == 3)
            cache_push((seq_t)next_candidate);
        next_candidate++;
    }
    return cache[n - 1];
}
